// GET /v1/tasks/{id}/trip and the boards' trip column (first-mile/page.tsx:136-141): the trips of the given tasks,
// newest first per task (trip_records_task).
func (q *Queries) TripsOfTasks(ctx context.Context, arg TripsOfTasksParams) ([]TripRecord, error) {
	rows, err := q.db.Query(ctx, tripsOfTasks,
		arg.TaskIds,
		arg.AllTenants,
		arg.TenantIds,
		arg.ReachDriver,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TripRecord{}
	for rows.Next() {
		var i TripRecord
		if err := rows.Scan(
			&i.ID,
			&i.LegacyDocID,
			&i.TenantID,
			&i.TenantSource,
			&i.TripNo,
			&i.Status,
			&i.JobType,
			&i.JobCategory,
			&i.TaskID,
			&i.LegacyTaskRef,
			&i.TaskRefMatch,
			&i.DriverID,
			&i.LegacyDriverRef,
			&i.DriverRefMatch,
			&i.OriginRaw,
			&i.OriginHubID,
			&i.DestinationRaw,
			&i.DestinationHubID,
			&i.DestinationSocKey,
			&i.SealCode,
			&i.PartnerCode,
			&i.OcrData,
			&i.TruckID,
			&i.TruckLicensePlateSnapshot,
			&i.TruckTypeRaw,
			&i.VehicleClass,
			&i.DistanceKm,
			&i.ParcelCount,
			&i.SealTime,
			&i.TotalWeightKg,
			&i.LoadingLat,
			&i.LoadingLng,
			&i.Std,
			&i.Sta,
			&i.Ata,
			&i.DurationMinutes,
			&i.DeliveredAt,
			&i.DeliveredLat,
			&i.DeliveredLng,
			&i.DeliveredVia,
			&i.IsMultiDelivery,
			&i.BillingPartyID,
			&i.BillingDate,
			&i.BillingAxisDate,
			&i.NeedsAdminReview,
			&i.ReviewStatus,
			&i.ReviewReason,
			&i.ResubmittedAt,
			&i.LineDeliveredNotifiedAt,
			&i.EvidenceToken,
			&i.EvidenceTokenRevokedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

