const upsertTripPhoto = `-- name: UpsertTripPhoto :one

INSERT INTO trip_photos (trip_id, stop_id, photo_type, file_id, geocode_lat, geocode_lng, geocode_address, geocoded_at,
                         position)
VALUES ($1, $2, $3, $4, $5,
        $6, $7, $8,
        coalesce((SELECT max(p.position) + 1 FROM trip_photos p WHERE p.trip_id = $1), 0))
ON CONFLICT (trip_id, photo_type) DO UPDATE
SET file_id = EXCLUDED.file_id, stop_id = EXCLUDED.stop_id, geocode_lat = EXCLUDED.geocode_lat,
    geocode_lng = EXCLUDED.geocode_lng, geocode_address = EXCLUDED.geocode_address, geocoded_at = EXCLUDED.geocoded_at,
    position = EXCLUDED.position
RETURNING id, trip_id, stop_id, photo_type, photo_type_known, file_id, geocode_lat, geocode_lng, geocode_address, geocoded_at, position, created_at, updated_at
`

type UpsertTripPhotoParams struct {
	TripID         uuid.UUID
	StopID         *uuid.UUID
	PhotoType      string
	FileID         uuid.UUID
	GeocodeLat     *float64
	GeocodeLng     *float64
	GeocodeAddress *string
	GeocodedAt     *time.Time
}

// --- photos (trip_photos: merge by type, last wins; R19 free-text type + STORED photo_type_known) ---------------
// One row per (trip, photo_type): a new file for a type replaces the old one (mergeTripPhotosReplacingTypes). Any
// non-empty type is stored (R19); photo_type_known is generated (TRIP_PHOTO_TYPE_ENUM or stop_{n}_*).
func (q *Queries) UpsertTripPhoto(ctx context.Context, arg UpsertTripPhotoParams) (TripPhoto, error) {
	row := q.db.QueryRow(ctx, upsertTripPhoto,
		arg.TripID,
		arg.StopID,
		arg.PhotoType,
		arg.FileID,
		arg.GeocodeLat,
		arg.GeocodeLng,
		arg.GeocodeAddress,
		arg.GeocodedAt,
	)
	var i TripPhoto
	err := row.Scan(
		&i.ID,
		&i.TripID,
		&i.StopID,
		&i.PhotoType,
		&i.PhotoTypeKnown,
		&i.FileID,
		&i.GeocodeLat,
		&i.GeocodeLng,
		&i.GeocodeAddress,
		&i.GeocodedAt,
		&i.Position,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
